using DotNetCloud.Modules.Sdk.Web;
using Microsoft.AspNetCore.Components;

namespace DotNetCloud.Modules.Bookmarks.Web.Layout;

/// <summary>
/// Shell for every Bookmarks page inside the core's frame.
/// </summary>
/// <remarks>
/// The layout owns the bridge subscription: the core shell pushes a theme/locale change whenever the
/// user toggles its theme, and the frame has to re-render to follow it. The <c>Bridge</c> property is
/// generated by the <c>@inject</c> directive in the markup file.
/// </remarks>
public partial class MainLayout : LayoutComponentBase, IAsyncDisposable
{
    /// <inheritdoc />
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender)
        {
            return;
        }

        await Bridge.InitializeAsync();
        Bridge.Changed += OnBridgeChanged;
    }

    private void OnBridgeChanged() => _ = InvokeAsync(StateHasChanged);

    /// <inheritdoc />
    public async ValueTask DisposeAsync()
    {
        Bridge.Changed -= OnBridgeChanged;
        await Task.CompletedTask;
    }
}
